/* Retention Intelligence: approved metrics, explicit provenance, no generated SQL. */
function navIcon(i){const paths=['M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z','M15 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0M4 21v-3a8 8 0 0 1 16 0v3','M2 12h4l3-7 5 14 3-7h5','M3 4h18v16H3zM3 10h18M10 4v16','M4 5h16v14H4zM8 9h8M8 13h5','M3 3v18h18M7 16l4-5 4 2 5-8','M3 4h18v16H3zM3 9h18M3 14h18M9 4v16M15 4v16','M4 21V10h4v11M10 21V3h4v18M16 21V7h4v14','M4 4h16v16H4zM8 8h8v8H8z','M5 3h10l4 4v14H5zM9 11h6M9 15h6','M12 3v3M12 18v3M3 12h3M18 12h3M7 7l-2-2M17 17l2 2M7 17l-2 2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0'];return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[i%paths.length]}"/></svg>`}
const baseFiltered=filtered;
let selection=new Set(),capacity=50,actionView='board',extraColumns=getStore('columns',false),savedViews=getStore('views',[]),secondarySort='name';
filtered=function(){return baseFiltered().sort((a,b)=>{const first=sort==='name'?a.name.localeCompare(b.name):sort==='value'?b.revenue-a.revenue:(b.probability??-1)-(a.probability??-1);return first||(secondarySort==='value'?b.revenue-a.revenue:a.name.localeCompare(b.name))})};
const originalMetric=metric;
metric=function(label,current,previous,type,tip,lower=false,trend=[]){let html=originalMetric(label,current,previous,type,tip,lower,trend);if(['Customers at risk','Predicted churn rate','Revenue at risk'].includes(label))html=html.replace(/<span class="delta[\s\S]*?<\/span> &nbsp; vs prior period/,'No comparable prior model snapshot');return html};
function currentPopulation(){const start=new Date(date(D.asOf)-period*86400000).toISOString().slice(0,10);return customers.filter(c=>c.first>=start)}
function recordTable(rows){if(!rows.length)return '<p class="empty">No eligible records in this selection.</p>';const cols=Object.keys(rows[0]);return `<div class="table-wrap evidence-table"><table><thead><tr>${cols.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(k=>`<td>${esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function productEvidence(){return D.products.map(p=>{const cs=currentPopulation().filter(c=>c.product===p.id),m=metrics(cs);return {product:p.name,n:cs.length,inactivity:m.churn,repeat:m.repeat}})}
function answerQuestion(question){const q=question.toLowerCase(),cs=currentPopulation();let result,title,definition,drill='Customer Intelligence';
 if(/product|categor/.test(q)){const rows=productEvidence().sort((a,b)=>b.inactivity-a.inactivity);title=`${rows[0].product} has the highest observed inactivity (${pct(rows[0].inactivity)}).`;definition='Share of purchasing customers past product refill date plus operational grace. Category mix is not controlled.';result=rows.map(r=>({Product:r.product,Customers:r.n,'Inactivity':pct(r.inactivity),'Repeat purchase':pct(r.repeat)}));drill='Product Analytics'}
 else if(/segment|repeat/.test(q)){result=['New','Active','Consistent','At-Risk','Dormant','Recovered'].map(stage=>{const x=cs.filter(c=>c.stage===stage);return {Segment:stage,Customers:x.length,'Repeat rate':pct(metrics(x).repeat)}});title='Repeat purchase by lifecycle segment';definition='Share with at least two completed orders. Lifecycle groups follow documented precedence.';drill='Customer Segments'}
 else if(/prioriti|attention|customer/.test(q)){result=cs.filter(c=>c.probability!=null).sort((a,b)=>b.probability*b.revenue-a.probability*a.revenue).slice(0,10).map(c=>({Customer:c.code,Name:c.name,Risk:pct(c.probability),'Value exposure':money(c.revenue*c.probability),Reason:reason(c)}));title='Priority customers by probability × observed customer value';definition='A triage score, not expected incremental recovery value. Intervention effectiveness is unmeasured.'}
 else if(/cohort/.test(q)){result=cohortRows().filter(r=>r.values[1]!=null).sort((a,b)=>a.values[1]-b.values[1]).slice(0,6).map(r=>({Cohort:r.month,Customers:r.size,'Month 1':pct(r.values[1])}));title='Lowest observed month-one purchase retention';definition='Share purchasing in the month after first completed purchase. Only fully observed months are included.';drill='Cohort Analysis'}
 else if(/intervention|action/.test(q)){result=['Pending','Assigned','In Progress','Contacted','Resolved','Unsuccessful'].map(s=>({Status:s,Cases:interventions.filter(i=>i.status===s).length}));title='Recorded intervention status';definition='Operational case counts. Outcomes are observational; no holdout experiment supports causal attribution.';drill='Retention Actions'}
 else if(/why|increase|month|trend/.test(q)){const ss=series(cs);result=ss.slice(-3).map(s=>({Month:s.label,'Inactivity':pct(s.churn),'Eligible purchasers':s.eligible}));title='Recent observed inactivity trend';definition='Refill-status prevalence among customers acquired in the selected period. This comparison cannot establish why a rate changed.'}
 else {title='This question is outside the approved metric catalogue.';definition='Try product inactivity, segment repeat purchase, priority customers, cohorts, interventions, or monthly trends. No arbitrary SQL or external AI service is used.';result=[]}
 return `<div class="answer"><h3>${esc(title)}</h3><p>${esc(definition)}</p><p class="forecast-note">Period: ${period}-day acquisition window ending ${D.asOf} · Population: ${fmt(cs.length)} synthetic customers. Cohort and intervention queries use their complete observed records.</p>${recordTable(result)}<button style="margin-top:14px" onclick="navigate('${drill}')">Inspect underlying workspace</button></div>`}
function askQuestion(e){e?.preventDefault();const q=document.getElementById('question').value.trim();if(!q)return;document.getElementById('answer').innerHTML=answerQuestion(q)}
function insightPanel(){const rows=productEvidence().sort((a,b)=>b.inactivity-a.inactivity),cs=currentPopulation(),withTickets=cs.filter(c=>c.openTickets),without=cs.filter(c=>!c.openTickets);return `<div class="two-grid">${panel('Product watch',`${period}-day acquisition population`, `<p style="line-height:1.8;font-size:12px">${esc(rows[0].product)}: <b>${pct(rows[0].inactivity)}</b> observed inactivity across ${rows[0].n} customers.</p><p class="forecast-note">Investigate acquisition mix and reorder timing before choosing an intervention.</p>`, '<button onclick="navigate(\'Product Analytics\')">Inspect</button>')}${panel('Support signal','Current unresolved-ticket snapshot',`<p style="line-height:1.8;font-size:12px">Inactivity with open tickets: <b>${pct(metrics(withTickets).churn)}</b> (n=${withTickets.length}); without: <b>${pct(metrics(without).churn)}</b> (n=${without.length}).</p><p class="forecast-note">Descriptive association; support resolution timestamps are unavailable.</p>`)}</div>`}
function anomalyRows(){const now=date(D.asOf),daily=[];for(let j=84;j>=1;j--){const ds=new Date(now-j*86400000).toISOString().slice(0,10),os=D.orders.filter(o=>o.date===ds);daily.push({date:ds,volume:os.filter(o=>o.status==='completed').length,n:os.length,cancel:os.filter(o=>o.status==='cancelled').length,refund:os.filter(o=>o.status==='refunded').length})}return daily.slice(-28).map((d,i)=>{const ix=i+56,peers=daily.slice(0,ix).filter(p=>date(p.date).getUTCDay()===date(d.date).getUTCDay()).map(p=>p.volume),mean=peers.reduce((s,n)=>s+n,0)/peers.length,sd=Math.sqrt(peers.reduce((s,n)=>s+(n-mean)**2,0)/peers.length),z=(d.volume-mean)/Math.max(Math.sqrt(mean),sd,1);return {Date:d.date,Orders:d.volume,'Weekday baseline':mean.toFixed(1),'Standardised deviation':z.toFixed(2),Signal:mean>=5&&Math.abs(z)>3?'Review':'Within range'}})}
function churnIntelligence(){const f=D.model.forecast;return header('Churn intelligence','Evidence, prioritisation, and an explicit view of uncertainty.')+`<div class="analysis-box"><h2>Retention Intelligence</h2><p class="forecast-note">Ask a business question. Answers use a constrained metric catalogue and the loaded records.</p><form class="analysis-input" onsubmit="askQuestion(event)"><input id="question" aria-label="Analytical question" placeholder="Which product category has the highest churn?"><button class="primary">Analyse</button></form><div class="query-examples">${['Which product has the highest churn?','Which customers should we prioritise?','Which cohorts have weakest retention?','Which interventions performed best?'].map(q=>`<button onclick="document.getElementById('question').value=this.textContent;askQuestion()">${q}</button>`).join('')}</div><div id="answer"></div></div>${insightPanel()}${f?panel('Commercial inactivity outlook',`${D.model.horizon}-day horizon · ${D.model.scored} currently active, scored customers`,`<div class="evidence-strip"><div><small>Expected newly inactive customers</small><strong>${fmt(f.expected)}</strong></div><div><small>Conditional 95% interval</small><strong>${fmt(f.lower)}–${fmt(f.upper)}</strong></div><div><small>Active model</small><strong style="font-size:14px">${esc(D.model.selected)}</strong></div></div><p class="forecast-note">${esc(f.method)} This is a synthetic-data model forecast, not a forecast for Man Matters. Repeat-purchase and revenue forecasts are unavailable.</p>`):''}<div class="section-rule"><h2>Daily order anomaly monitor</h2><small>28 days · matched weekday baseline · 3σ threshold</small></div>${recordTable(anomalyRows())}<p class="forecast-note">Low-volume baselines below five daily orders are suppressed. Flags are statistical deviations for investigation, not proof of a business incident.</p>`}
function overviewV2(){const html=overview();return html.replace('Start with high-value customers who missed their refill.','Review active customers with elevated predicted inactivity.').replace('A clearer picture of customer health. A smarter path to retention.','Commercial health, intervention priorities, and measurable customer behaviour.').replace(/<div class="forecast-note">Comparisons[\s\S]*?<\/div>/,'')+`<div class="section-rule"><h2>Investigate next</h2><button onclick="navigate('Churn Intelligence')">Open Retention Intelligence</button></div>${insightPanel()}<div class="two-grid">${panel('Acquisition and repeat behaviour','By acquisition month; completed order records',recordTable(cohortRows().slice(-5).map(r=>({Cohort:r.month,Acquired:r.size,'Month-one return':r.values[1]==null?'Not mature':pct(r.values[1])}))))}${panel('Intervention progress','Recorded operational outcomes',recordTable(['Contacted','Resolved','Unsuccessful'].map(status=>({Status:status,Cases:interventions.filter(i=>i.status===status).length}))),'<button onclick="navigate(\'Retention Actions\')">Open actions</button>')}</div>`}
function saveView(){const name=document.getElementById('view-name').value.trim();if(!name){toast('Enter a name for this view.');return}savedViews=savedViews.filter(v=>v.name!==name);savedViews.push({name,query,riskFilter,productFilter,channelFilter,segmentFilter,valueFilter,lastFilter,frequencyFilter,sort,secondarySort});put('views',savedViews);renderContent();toast('Customer view saved.')}
function restoreView(i){const v=savedViews[Number(i)];if(!v)return;({query,riskFilter,productFilter,channelFilter,segmentFilter,valueFilter,lastFilter,frequencyFilter,sort,secondarySort}=v);page=1;renderContent()}
function workspaceV2(){let html=intelligence();const controls=`<div class="workbar"><input id="view-name" aria-label="Saved view name" placeholder="Name this view"><button onclick="saveView()">Save view</button><select aria-label="Saved customer views" onchange="restoreView(this.value)"><option value="">Saved views</option>${savedViews.map((v,i)=>`<option value="${i}">${esc(v.name)}</option>`).join('')}</select><span class="spacer"></span><label>Then sort <select onchange="secondarySort=this.value;renderContent()">${options(['name','value'],secondarySort)}</select></label><button onclick="extraColumns=!extraColumns;put('columns',extraColumns);renderContent()">${extraColumns?'Compact columns':'More columns'}</button><button onclick="bulkActions()">Create actions (${selection.size})</button></div>`;html=html.replace('<div class="table-wrap">',controls+'<div class="table-wrap">');html=html.replace('<th>Customer</th>','<th>Select</th><th>Customer</th>');const rows=filtered().slice((page-1)*12,page*12);for(const c of rows){html=html.replace(`<tr class="clickable" tabindex="0" onkeydown="if(event.key==='Enter')profile(${c.id})" onclick="profile(${c.id})"><td>`,`<tr class="clickable" tabindex="0" onkeydown="if(event.key==='Enter')profile(${c.id})" onclick="profile(${c.id})"><td onclick="event.stopPropagation()"><input type="checkbox" aria-label="Select ${c.code}" ${selection.has(c.id)?'checked':''} onchange="this.checked?selection.add(${c.id}):selection.delete(${c.id});renderContent()"></td><td>`);}if(extraColumns)html=html.replace('<th></th></tr>','<th>Last order</th><th>Orders</th><th>Avg interval</th><th>Owner</th><th></th></tr>');if(extraColumns)html=html.replace(/(<tr class="clickable"[^>]*onclick="profile\((\d+)\)">)([\s\S]*?)(<\/tr>)/g,(all,head,id,body,end)=>{const c=customers[Number(id)];return head+body.replace('<td style="color:#809274">↗</td>',`<td>${short(c.last)}</td><td>${c.count}</td><td>${c.freq?Math.round(c.freq)+'d':'—'}</td><td>${esc(interventions.find(i=>i.customer===c.id)?.assignee||'Unassigned')}</td><td>↗</td>`)+end});return html}
async function bulkActions(){if(settings.role==='Business Analyst'){toast('Analysts have read-only access to actions.');return}if(!selection.size){toast('Select customers first.');return}let n=0;try{for(const id of selection){if(interventions.some(i=>i.customer===id&&!['Resolved','Unsuccessful'].includes(i.status)))continue;const c=customers[id],v={customer_id:id,action:recommendation(c),assignee:'Unassigned',deadline:'2026-11-04',status:'Pending',notes:'Created from customer selection',outcome:'Not observed'};if(apiMode)await api('interventions','POST',v);else interventions.unshift({...v,customer:id,id:Date.now()+n,created:D.asOf,history:[]});n++}if(apiMode)await syncOperations();else put('interventions',interventions);selection.clear();renderContent();toast(`${n} actions created. Existing open follow-ups were skipped.`)}catch(e){toast(e.message)}}
function actionsV2(){const intro=header('Retention actions','A focused queue for your team. Prioritise, assign, and follow through.',false)+`<div class="workbar"><button onclick="actionView='board';renderContent()">Board</button><button onclick="actionView='table';renderContent()">Table</button><span class="spacer"></span><label>Queue capacity <select onchange="capacity=Number(this.value);renderContent()">${[25,50,100].map(n=>`<option ${capacity===n?'selected':''}>${n}</option>`).join('')}</select></label><button onclick="navigate('Customer Intelligence')">Select customers</button></div>`;if(actionView==='table')return intro+interventionCentre();return intro+`<p class="forecast-note" style="margin:15px 0">${apiMode?'Database-backed':'Browser-local'} demonstration records. Priority orders cases by current probability × historical value. No incremental benefit is assumed.</p><div class="kanban">${['Pending','Assigned','In Progress','Contacted','Resolved','Unsuccessful'].map(status=>{const list=interventions.filter(i=>i.status===status).sort((a,b)=>{const x=customers[a.customer],y=customers[b.customer];return (y.probability||0)*y.revenue-(x.probability||0)*x.revenue}).slice(0,capacity);return `<div class="kanban-column"><h3>${status} · ${list.length}</h3>${list.map(i=>{const c=customers[i.customer];return `<article class="work-item"><b>${c.name}</b><p>${c.code} · ${c.probability==null?'Not scored':pct(c.probability)}<br>${reason(c)}</p><p>${esc(i.assignee)} · due ${short(i.deadline)}<br>${esc(i.outcome)}</p><button onclick="interventionForm(${c.id},${i.id})">Manage action</button></article>`}).join('')||'<small>No cases in this stage</small>'}</div>`}).join('')}</div>`}
function modelV2(){const m=D.model;if(!m.monitoring)return prediction();return header('Model intelligence','Performance, provenance, and the boundaries of the active model.',false)+`<div class="evidence-strip"><div><small>Active version</small><strong style="font-size:14px">${esc(m.version)}</strong><small>${m.selected}</small></div><div><small>Scored population</small><strong>${fmt(m.scored)}</strong><small>Currently active purchasers only</small></div><div><small>Release gate</small><strong style="font-size:16px">${m.accepted?'Passed':'Not accepted'}</strong><small>PR-AUC and Brier versus prevalence baseline</small></div></div><div class="notice">Synthetic demonstration · Already-inactive customers are excluded from incident-risk prediction. Commercial inactivity does not establish treatment discontinuation. SKU, pack-size, subscription, and multi-item history are unavailable.</div>${prediction().replace(/<div class="page-head">[\s\S]*?<\/div><\/div>/,'')}<div class="section-rule"><h2>Intervention capacity evaluation</h2></div>${recordTable(Object.entries(m.metrics).map(([name,r])=>({Model:name,'Top K':r.capacity,'Precision @ K':pct(r.precision_at_k),'Recall @ K':pct(r.recall_at_k),Lift:r.lift.toFixed(2)+'×'})))}<div class="section-rule"><h2>Product-level validation</h2></div>${recordTable(m.subgroups.map(r=>({Product:r.product,Sample:r.population,Recall:pct(r.recall),'PR-AUC':pct(r.pr_auc),Brier:r.brier.toFixed(3)})))}<div class="section-rule"><h2>Feature monitoring</h2><small>Current eligible population versus training</small></div>${recordTable(m.monitoring.map(r=>({Feature:r.feature,'Missing':pct(r.missing_rate),'Mean shift / train σ':r.standardised_shift.toFixed(2),Signal:r.standardised_shift>1?'Investigate shift':'Within review threshold'})))}<div class="section-rule"><h2>Data quality and model operations</h2></div><div class="panel"><p class="section-intro">${m.quality.issues.length?esc(m.quality.issues.join(', ')):'No blocking identifier, order-status, timestamp, product-reference, or consumption-cycle errors.'} ${fmt(m.quality.orders)} orders checked. Dataset ${m.dataset_version}.</p><p class="forecast-note">Candidate runs are stored separately with metrics and model artifacts. Training alone never replaces the active model. New labels and historical prediction snapshots are not available for live degradation or score-distribution monitoring.</p><button onclick="trainingInfo()">Training run controls</button></div>`}
async function startCandidate(){try{const r=await api('training/runs','POST');toast('Candidate training queued; active model unchanged.')}catch(e){toast(e.message)}}
function trainingInfo(){openDrawer(`<div class="drawer-head"><h2>Model training</h2><button onclick="closeDrawer()">Close</button></div><div class="panel"><h2>Candidate-first release process</h2><p class="section-intro">Run the Python training service to compare three models, calibrate predictions, and save a candidate report. Promotion is explicit and requires baseline PR-AUC and Brier acceptance gates.</p><code>python -m backend.train_v2</code>${apiMode?'<button class="primary" onclick="startCandidate()">Train candidate model</button>':''}<p class="forecast-note">The hosted static workspace cannot execute Python jobs. The FastAPI deployment supports background candidate training for authorised managers and analysts; promotion remains an explicit operator action. Existing immutable runs are included with the source.</p></div>`)}
Object.assign(labels,{recency_ratio:'Recency relative to product cycle',average_interval:'Average order interval',interval_variability:'Order interval variability',refund_rate:'Refund rate',ticket_count:'Prior support contacts',engagement_change:'Change in recent engagement',average_order_value:'Average order value',discount_fraction:'Observed discount fraction',category_diversity:'Purchased category count'});
init();
